/**
 * Node.js port of dataset/bencoder/test4.py
 *
 *   import argparse
 *   import bencoder
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *   print(result)
 *
 * Run it exactly like the reference executable:
 *   node test4.mjs --a '9:value'      ->  b'value'
 */

import { ArgumentParser, SystemExit } from './lib/argparse/index.mjs';
import { decode } from './lib/bencoder/index.mjs';
import { encodeAscii } from './lib/codecs/ascii.mjs';
import { pyStr } from './lib/pytypes/repr.mjs';
import {
  CARET_DECODE_CALL,
  CARET_ENCODE_CALL,
  PyException,
  PyUnicodeEncodeError,
  formatTraceback,
} from './lib/runtime/exceptions.mjs';
import { exitWith, printLine, writeStderr } from './lib/runtime/stdio.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const result = decode(encodeAscii(args.a));
  printLine(pyStr(result));
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    exitWith(error.status);
  } else if (error instanceof PyException) {
    // An uncaught Python exception: traceback on stderr, exit status 1. The
    // underlined sub-expression depends on which call raised.
    const caret = error instanceof PyUnicodeEncodeError ? CARET_ENCODE_CALL : CARET_DECODE_CALL;
    writeStderr(formatTraceback(error, caret));
    exitWith(1);
  } else {
    throw error;
  }
}

/**
 * Re-implementation of the `bencoder` package's decoder, derived purely from
 * the observable behaviour of the reference program.
 *
 * The library is a thin recursive descent parser with several quirks that a
 * "correct" bencode implementation would not have; all of them are reproduced
 * here because they are observable:
 *
 *   * A byte-string length prefix is *not* validated against the remaining
 *     input — the slice is simply clamped, so `9:value` yields `b'value'` and
 *     `100:ab` yields `b'ab'`.
 *   * Dicts are built with `dict(zip(items[::2], items[1::2]))`, so an odd
 *     number of members silently drops the dangling key: `d3:cowe` -> `{}`.
 *   * An unrecognised leading byte is *printed* to stdout as an integer before
 *     the parser fails with a bare `AssertionError`.
 *   * Nothing validates the integer syntax beyond the regex, hence
 *     `i042e` -> 42 and `i-0e` -> 0.
 *
 * Line numbers in the raised frames mirror `bencoder.py` so the rendered
 * traceback matches the reference byte for byte.
 */

import { Bytes, EMPTY_BYTES, isAsciiDigitByte } from '../pytypes/bytestring.mjs';
import { pyIntFromDecimal } from '../pytypes/pyint.mjs';
import { pyDictFromFlatItems } from '../pytypes/pydict.mjs';
import { pyIntRepr } from '../pytypes/pyint.mjs';
import { printLine } from '../runtime/stdio.mjs';
import {
  PyAssertionError,
  PyAttributeError,
  PyIndexError,
  PyRecursionError,
  PyTypeError,
  pushFrame,
} from '../runtime/exceptions.mjs';

const MODULE = 'bencoder.py';

const LINE_INT_GROUP = 67; // int(m.group(1)) — m is None for malformed ints
const LINE_RECURSE = 72; // v, x = decode_first(x)
const LINE_DICT_BUILD = 78; // dict(zip(items[::2], items[1::2]))
const LINE_FIRST_BYTE = 79; // elif chr(x[0]).isdigit()
const LINE_STR_GROUP = 81; // int(m.group(1)) for the length prefix
const LINE_PRINT_BYTE = 87; // print(x[0])
const LINE_ASSERT = 88; // assert False
const LINE_DECODE_CALL = 93; // r, rest = decode_first(x)
const LINE_MALFORMED = 95; // raise TypeError('Malformed input.')

/**
 * CPython's default recursion limit is 1000 frames. Two are already in use
 * (`<module>` and `decode`), so the 999th nested `decode_first` is the one that
 * fails — `'l' * 998 + 'e' * 998` decodes, one level deeper raises.
 */
const MAX_DECODE_DEPTH = 998;

const RE_INT = /^i(-?\d+)e/;
const RE_STRING_LENGTH = /^(\d+):/;

function frame(line, func) {
  return { file: MODULE, line, func };
}

function raiseAt(error, line) {
  error.pyFrames = [frame(line, 'decode_first')];
  throw error;
}

/**
 * `decode_first(x) -> (value, rest)`
 *
 * @param {Bytes} x
 * @param {number} depth 1 for the outermost call
 * @returns {[unknown, Bytes]}
 */
export function decodeFirst(x, depth) {
  if (depth > MAX_DECODE_DEPTH) throw new PyRecursionError();

  if (x.startsWith('i')) {
    const match = RE_INT.exec(x.raw);
    if (match === null) {
      raiseAt(new PyAttributeError("'NoneType' object has no attribute 'group'"), LINE_INT_GROUP);
    }
    return [pyIntFromDecimal(match[1]), x.sliceFrom(match[0].length)];
  }

  if (x.startsWith('l') || x.startsWith('d')) {
    const isDict = x.startsWith('d');
    let rest = x.sliceFrom(1);
    const items = [];
    while (!rest.startsWith('e')) {
      let value;
      try {
        [value, rest] = decodeFirst(rest, depth + 1);
      } catch (error) {
        throw pushFrame(error, frame(LINE_RECURSE, 'decode_first'));
      }
      items.push(value);
    }
    const tail = rest.sliceFrom(1);
    if (isDict) {
      try {
        return [pyDictFromFlatItems(items), tail];
      } catch (error) {
        if (error instanceof PyTypeError) raiseAt(error, LINE_DICT_BUILD);
        throw error;
      }
    }
    return [items, tail];
  }

  // `chr(x[0]).isdigit()` — indexing an empty bytes object raises here.
  const firstByte = x.byteAt(0);
  if (firstByte === undefined) {
    raiseAt(new PyIndexError('index out of range'), LINE_FIRST_BYTE);
  }

  if (isAsciiDigitByte(firstByte)) {
    const match = RE_STRING_LENGTH.exec(x.raw);
    if (match === null) {
      raiseAt(new PyAttributeError("'NoneType' object has no attribute 'group'"), LINE_STR_GROUP);
    }
    const declaredLength = pyIntFromDecimal(match[1]);
    const bodyStart = match[0].length;
    return [x.sliceCount(bodyStart, declaredLength), x.sliceAfter(bodyStart, declaredLength)];
  }

  // The library prints the offending byte value before giving up.
  printLine(pyIntRepr(BigInt(firstByte))); // LINE_PRINT_BYTE
  raiseAt(new PyAssertionError(), LINE_ASSERT);
  return [EMPTY_BYTES, EMPTY_BYTES]; // unreachable
}

/**
 * `decode(x)` — parse one value and reject any trailing bytes.
 *
 * @param {Bytes} x
 */
export function decode(x) {
  let result;
  let rest;
  try {
    [result, rest] = decodeFirst(x, 1);
  } catch (error) {
    throw pushFrame(error, frame(LINE_DECODE_CALL, 'decode'));
  }

  if (rest.length !== 0) {
    const error = new PyTypeError('Malformed input.');
    error.pyFrames = [frame(LINE_MALFORMED, 'decode')];
    throw error;
  }
  return result;
}

/**
 * `repr()` for the value graph bencoder returns: int, bytes, list, dict.
 *
 * `print(value)` uses `str(value)`, and for every one of these types
 * `str is repr` (containers always repr their members), so a single
 * implementation covers both.
 */

import { Bytes } from './bytestring.mjs';
import { PyDict } from './pydict.mjs';
import { pyIntRepr } from './pyint.mjs';

/**
 * `repr(bytes)`, following CPython's `bytes_repr`:
 *   * the literal is single-quoted unless it contains `'` and no `"`,
 *   * the active quote and backslash are backslash-escaped,
 *   * tab / newline / carriage return get their short escapes,
 *   * every other byte outside the printable ASCII range becomes `\xNN`.
 */
export function pyBytesRepr(value) {
  const raw = value.raw;
  const quote = raw.includes("'") && !raw.includes('"') ? '"' : "'";

  let body = '';
  for (let index = 0; index < raw.length; index += 1) {
    const ch = raw[index];
    const code = raw.charCodeAt(index);
    if (ch === quote || ch === '\\') body += `\\${ch}`;
    else if (code === 0x09) body += '\\t';
    else if (code === 0x0a) body += '\\n';
    else if (code === 0x0d) body += '\\r';
    else if (code < 0x20 || code >= 0x7f) body += `\\x${code.toString(16).padStart(2, '0')}`;
    else body += ch;
  }
  return `b${quote}${body}${quote}`;
}

export function pyRepr(value) {
  if (typeof value === 'bigint') return pyIntRepr(value);
  if (value instanceof Bytes) return pyBytesRepr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof PyDict) {
    const body = value
      .entries()
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  return String(value);
}

/** `str(value)` — identical to `repr` for every type reachable here. */
export const pyStr = pyRepr;
=====BYTESTRING
/**
 * `Bytes` — an immutable byte sequence modelled on CPython's `bytes`.
 *
 * Representation: a plain JS string in which every code unit holds one byte
 * value (0..255). The source program only ever produces bytes via
 * `str.encode('ascii')`, so in practice every code unit is < 128. Keeping the
 * payload in a string lets us reuse JS string search/slice primitives and the
 * regular-expression engine directly, which is exactly what CPython's
 * `re.match(b'...', x)` does on the bytes side.
 */

export class Bytes {
  /** @param {string} raw one code unit per byte */
  constructor(raw) {
    /** @type {string} */
    this.raw = raw;
    Object.freeze(this);
  }

  /** `len(x)` */
  get length() {
    return this.raw.length;
  }

  /** `x[i]` — the integer byte value, or `undefined` when out of range. */
  byteAt(index) {
    if (index < 0 || index >= this.raw.length) return undefined;
    return this.raw.charCodeAt(index);
  }

  /** `x.startswith(prefix)` where `prefix` is given as a JS string. */
  startsWith(prefix) {
    return this.raw.startsWith(prefix);
  }

  /** `x[start:]` with Python's clamping semantics for non-negative `start`. */
  sliceFrom(start) {
    if (start <= 0) return this;
    if (start >= this.raw.length) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start));
  }

  /**
   * `x[start:start + count]`.
   *
   * `count` may be a bigint far beyond the sequence length — bencoded length
   * prefixes are arbitrary-precision integers and CPython simply clamps the
   * slice, which is why `b'9:value'` decodes to `b'value'`.
   */
  sliceCount(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    if (take <= 0n) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start, start + Number(take)));
  }

  /** `x[start + count:]`, clamped the same way as {@link sliceCount}. */
  sliceAfter(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    return this.sliceFrom(start + Number(take));
  }

  equals(other) {
    return other instanceof Bytes && other.raw === this.raw;
  }
}

export const EMPTY_BYTES = new Bytes('');

/** True when the byte is an ASCII decimal digit, i.e. `chr(b).isdigit()`. */
export function isAsciiDigitByte(byte) {
  return byte !== undefined && byte >= 0x30 && byte <= 0x39;
}

/**
 * Python-flavoured exception objects plus the traceback renderer.
 *
 * The reference program is a frozen (PyInstaller) build of `test4.py`, so an
 * uncaught exception produces:
 *
 *   Traceback (most recent call last):
 *     File "test4.py", line 8, in <module>
 *       result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *                ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *     File "bencoder.py", line 93, in decode
 *     File "bencoder.py", line 88, in decode_first
 *   AssertionError
 *
 * Frames inside the frozen library have no source line available, so only the
 * `File ...` line is emitted for them. Exit status for an uncaught exception
 * is 1.
 */

import { formatSourceLines, getLine } from './linecache.mjs';

export class PyException extends Error {
  constructor(typeName, detail) {
    super(detail == null ? typeName : `${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail == null ? null : detail;
    /** @type {Array<{file: string, line: number, func: string}>} */
    this.pyFrames = [];
  }

  /** Final traceback line: `TypeError: Malformed input.` or bare `AssertionError`. */
  get exceptionLine() {
    return this.detail == null ? this.typeName : `${this.typeName}: ${this.detail}`;
  }
}

export class PyIndexError extends PyException {
  constructor(detail) {
    super('IndexError', detail);
  }
}

export class PyAttributeError extends PyException {
  constructor(detail) {
    super('AttributeError', detail);
  }
}

export class PyTypeError extends PyException {
  constructor(detail) {
    super('TypeError', detail);
  }
}

export class PyAssertionError extends PyException {
  constructor() {
    super('AssertionError', null);
  }
}

export class PyRecursionError extends PyException {
  constructor() {
    super('RecursionError', 'maximum recursion depth exceeded');
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(detail) {
    super('UnicodeEncodeError', detail);
  }
}

/** Record a caller frame while an exception propagates outwards. */
export function pushFrame(error, frame) {
  if (error instanceof PyException) error.pyFrames.unshift(frame);
  return error;
}

/** The `<module>` frame of test4.py, line 8. */
const MODULE_FILENAME = 'test4.py';
const MODULE_LINENO = 8;

/**
 * CPython 3.11+ underlines the sub-expression that raised. Two spans occur
 * here, given as the 0-based byte columns the code object records for line 8
 * (`result = bencoder.decode(args.a.encode('ascii'))  # ...`):
 * the whole `bencoder.decode(...)` call, and the inner `args.a.encode('ascii')`
 * call when the ASCII encode itself fails.
 */
export const CARET_DECODE_CALL = 'decode-call';
export const CARET_ENCODE_CALL = 'encode-call';

const CARET_SPANS = {
  [CARET_DECODE_CALL]: { colno: 9, endColno: 48 },
  [CARET_ENCODE_CALL]: { colno: 25, endColno: 47 },
};

/** CPython's `traceback._RECURSIVE_CUTOFF`. */
const RECURSIVE_CUTOFF = 3;

function formatFrames(frames) {
  const lines = [];
  let lastKey = null;
  let count = 0;

  const flush = () => {
    if (count > RECURSIVE_CUTOFF) {
      const extra = count - RECURSIVE_CUTOFF;
      lines.push(`  [Previous line repeated ${extra} more time${extra > 1 ? 's' : ''}]`);
    }
  };

  for (const frame of frames) {
    const key = `${frame.file}:${frame.line}:${frame.func}`;
    if (key !== lastKey) {
      flush();
      lastKey = key;
      count = 0;
    }
    count += 1;
    if (count > RECURSIVE_CUTOFF) continue;
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    if (frame.caretSpan !== undefined) {
      // Frames inside the frozen library have no readable source; the script
      // frame does, provided ./test4.py is where the process was started.
      lines.push(...formatSourceLines(getLine(frame.file, frame.line), frame.caretSpan));
    }
  }
  flush();
  return lines;
}

/**
 * Render the full traceback text (including the trailing newline) for an
 * exception escaping line 8 of test4.py.
 */
export function formatTraceback(error, caretSpan) {
  const frames = [
    {
      file: MODULE_FILENAME,
      line: MODULE_LINENO,
      func: '<module>',
      caretSpan: CARET_SPANS[caretSpan],
    },
    ...(error instanceof PyException ? error.pyFrames : []),
  ];

  const lines = ['Traceback (most recent call last):', ...formatFrames(frames)];
  lines.push(error instanceof PyException ? error.exceptionLine : String(error));
  // The frozen-executable epilogue; the number is the reporting process id.
  lines.push(`[PYI-${process.pid}:ERROR] Failed to execute script 'test4' due to unhandled exception!`);
  return `${lines.join('\n')}\n`;
}

/**
 * `PyDict` — an insertion-ordered mapping with Python's key semantics.
 *
 * bencoder builds its result with `dict(zip(items[::2], items[1::2]))`, so:
 *   * key order follows first insertion,
 *   * re-assigning an existing key keeps its original position but replaces
 *     the value,
 *   * an unhashable key (a decoded list or dict) raises
 *     `TypeError: unhashable type: 'list'` / `'dict'`.
 */

import { Bytes } from './bytestring.mjs';
import { PyTypeError } from '../runtime/exceptions.mjs';

/** `type(value).__name__` for the values bencoder can produce. */
export function pyTypeName(value) {
  if (typeof value === 'bigint') return 'int';
  if (value instanceof Bytes) return 'bytes';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyDict) return 'dict';
  return 'object';
}

/**
 * A stable identity token standing in for `hash()` + `==`. `bytes` and `int`
 * keys never compare equal to one another, so tagging the namespace is enough.
 */
function hashKey(key) {
  if (typeof key === 'bigint') return `i:${key.toString(10)}`;
  if (key instanceof Bytes) return `b:${key.raw}`;
  throw new PyTypeError(`unhashable type: '${pyTypeName(key)}'`);
}

export class PyDict {
  constructor() {
    /** @type {Map<string, {key: unknown, value: unknown}>} */
    this._slots = new Map();
  }

  set(key, value) {
    const token = hashKey(key);
    const existing = this._slots.get(token);
    if (existing !== undefined) existing.value = value;
    else this._slots.set(token, { key, value });
  }

  get size() {
    return this._slots.size;
  }

  /** Key/value pairs in insertion order. */
  entries() {
    return [...this._slots.values()].map(({ key, value }) => [key, value]);
  }
}

/**
 * `dict(zip(keys, values))` where `items` alternates key, value, key, value…
 * A trailing key with no matching value is dropped, exactly like `zip`
 * truncating to the shorter sequence — this is why `d3:cowe` decodes to `{}`.
 */
export function pyDictFromFlatItems(items) {
  const result = new PyDict();
  const pairs = Math.floor(items.length / 2);
  for (let index = 0; index < pairs; index += 1) {
    result.set(items[index * 2], items[index * 2 + 1]);
  }
  return result;
}
===PYINT
/**
 * Arbitrary-precision integers, matching Python's unbounded `int`.
 *
 * A bencoded integer such as `i123456789012345678901234567890e` decodes to an
 * exact value in Python, so `bigint` is the only faithful JS counterpart.
 */

/**
 * `int(text)` for the digit runs produced by bencoder's regexes: an optional
 * leading `-` followed by one or more ASCII digits. Leading zeros are legal
 * (`int('042') == 42`) and `-0` collapses to `0`.
 */
export function pyIntFromDecimal(text) {
  const negative = text.startsWith('-');
  const digits = negative ? text.slice(1) : text;
  const magnitude = BigInt(stripLeadingZeros(digits));
  return negative ? -magnitude : magnitude;
}

function stripLeadingZeros(digits) {
  let index = 0;
  while (index < digits.length - 1 && digits[index] === '0') index += 1;
  return digits.slice(index);
}

/** `repr(n)` / `str(n)` for a Python int. */
export function pyIntRepr(value) {
  return value.toString(10);
}
===ASCII
/**
 * `str.encode('ascii')` with CPython's strict error handler.
 *
 * On the first run of non-ASCII characters CPython raises
 * `UnicodeEncodeError`, whose message reports code-point *string* indices —
 * an astral character counts as one position even though JS stores it as a
 * surrogate pair.
 */

import { Bytes } from '../pytypes/bytestring.mjs';
import { PyUnicodeEncodeError } from '../runtime/exceptions.mjs';

/** How CPython spells the offending character inside the error message. */
function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

const REASON = 'ordinal not in range(128)';

/**
 * @param {string} text
 * @returns {Bytes}
 */
export function encodeAscii(text) {
  // Code points, so that positions match Python string indices.
  const codePoints = [...text].map((ch) => ch.codePointAt(0));

  let start = -1;
  for (let index = 0; index < codePoints.length; index += 1) {
    if (codePoints[index] >= 0x80) {
      start = index;
      break;
    }
  }

  if (start === -1) return new Bytes(text);

  // CPython reports the whole maximal run of unencodable characters.
  let end = start + 1;
  while (end < codePoints.length && codePoints[end] >= 0x80) end += 1;

  const detail =
    end - start === 1
      ? `'ascii' codec can't encode character '${escapeCodePoint(codePoints[start])}' in position ${start}: ${REASON}`
      : `'ascii' codec can't encode characters in position ${start}-${end - 1}: ${REASON}`;
  throw new PyUnicodeEncodeError(detail);
}
